//! Optional export-only interaction sounds and an original quiet ambient bed.
use super::*;
use std::io::Cursor;
#[derive(Clone,Copy)]struct Event{start:usize,clip:usize,gain:f32}
fn pcm(bytes:&[u8])->Res<Vec<f32>>{let mut reader=hound::WavReader::new(Cursor::new(bytes)).map_err(|e|e.to_string())?;let spec=reader.spec();if spec.channels!=1||spec.bits_per_sample!=16||spec.sample_rate!=22050{return Err("Invalid bundled soundtrack asset.".into());}let raw=reader.samples::<i16>().map(|s|s.map(|n|n as f32/32768.)).collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;let length=(raw.len()as u64*48000/22050)as usize;Ok((0..length).map(|i|{let x=i as f64*22050./48000.;let a=x as usize;let b=(a+1).min(raw.len()-1);raw[a]*(1.-x.fract()as f32)+raw[b]*x.fract()as f32}).collect())}
pub(super) fn render(job:&Session,camera:Option<&cinematic::Track>,control:&export::Control)->Res<Option<PathBuf>>{
 let c=&job.config;if !c.interaction_sounds&&!c.background_music{return Ok(None);}let duration=job.segments.iter().map(|s|s.duration).sum::<f64>();let mut events=Vec::new();let mut base=0.;let(mut click,mut last_type)=(-1.,-1.);
 if c.interaction_sounds{for(i,segment)in job.segments.iter().enumerate(){let path=project::assets_dir(job).join(format!("cursor-{i}.jsonl"));let samples=project::read_cursor(&path,job.bounds.w,job.bounds.h,segment.duration,control)?;let mut down=false;for s in samples{let time=base+s.time;let pressed=s.buttons!=0;if pressed&&!down&&s.inside&&time-click>0.07{events.push(Event{start:(time*48000.).round()as usize,clip:0,gain:0.14});click=time;}down=pressed;if s.context.as_ref().is_some_and(|c|c.activity&(context::TYPE|context::TAB|context::ENTER)!=0)&&time-last_type>0.035{events.push(Event{start:(time*48000.).round()as usize,clip:1,gain:0.075});last_type=time;}}base+=segment.duration;}
  if let Some(camera)=camera{let mut last=0i8;let mut previous=-10.;for(i,pair)in camera.frames.windows(2).enumerate(){let dz=pair[1].zoom-pair[0].zoom;let sign=if dz>0.0004{1}else if dz< -0.0004{-1}else{0};let time=i as f64/c.fps as f64;if sign!=0&&sign!=last&&time-previous>0.3{events.push(Event{start:(time*48000.).round()as usize,clip:2,gain:0.028});previous=time;}last=sign;}}
 }
 events.sort_by_key(|e|e.start);let clips=[pcm(include_bytes!("../resources/audio/click_001.wav"))?,pcm(include_bytes!("../resources/audio/tick_001.wav"))?,pcm(include_bytes!("../resources/audio/soft-whoosh.wav"))?];let music=if c.background_music{pcm(include_bytes!("../resources/audio/soft-ambient.wav"))?}else{Vec::new()};let path=job.dir.join("cinematic-soundtrack.wav");let mut writer=hound::WavWriter::create(&path,hound::WavSpec{channels:1,sample_rate:48000,bits_per_sample:16,sample_format:hound::SampleFormat::Int}).map_err(|e|e.to_string())?;let length=(duration*48000.).round()as usize;let mut active=Vec::<Event>::new();let mut next=0;
 for frame in 0..length{if frame%4096==0&&control.cancelled(){return Err("Recording cancelled.".into());}while next<events.len()&&events[next].start<=frame{active.push(events[next]);next+=1;}active.retain(|e|frame-e.start<clips[e.clip].len());let mut value=active.iter().map(|e|clips[e.clip][frame-e.start]*e.gain).sum::<f32>();if !music.is_empty(){let fade=(frame as f32/38400.).min(1.)*((length-frame)as f32/48000.).min(1.);value+=music[frame%music.len()]*0.10*fade;}writer.write_sample((value.clamp(-0.95,0.95)*32767.)as i16).map_err(|e|e.to_string())?;}
 writer.finalize().map_err(|e|e.to_string())?;Ok(Some(path))
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn bundled_assets_are_valid(){for bytes in [include_bytes!("../resources/audio/click_001.wav").as_slice(),include_bytes!("../resources/audio/tick_001.wav").as_slice(),include_bytes!("../resources/audio/soft-whoosh.wav").as_slice(),include_bytes!("../resources/audio/soft-ambient.wav").as_slice()]{let samples=pcm(bytes).unwrap();assert!(!samples.is_empty());assert!(samples.iter().all(|v|v.is_finite()&&v.abs()<=1.));}}
}
